/// <summary>
/// Controller class to invoke automate posting of finalization 
/// </summary>
class METSalesOrderFinalizationAutomateController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Main method to initiate class
/// </summary>
/// <param name = "_args">Args reference</param>
public static void main(Args _args)
{
    METSalesOrderFinalizationAutomateContract   contract;
    METSalesOrderFinalizationAutomateController controller      = METSalesOrderFinalizationAutomateController::construct(_args);

    contract = controller.getDataContractObject() as METSalesOrderFinalizationAutomateContract;

    contract.parmThreadCount(WHSParameters::find().METFinalisationThreadCount);
    contract.parmOrderTransactionType(_args.parmEnum());
    controller.batchInfo().parmBatchExecute(true);
    controller.startOperation();
}

/// <summary>
/// Construct class to create instance
/// </summary>
/// <param name = "_args">Args reference</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>Controller class</returns>
public static METSalesOrderFinalizationAutomateController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METSalesOrderFinalizationAutomateController controller = new METSalesOrderFinalizationAutomateController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>
/// Load from last user input
/// </summary>
protected void loadFromSysLastValue()
{
    //super();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METSalesOrderFinalizationAutomateService), methodstr(METSalesOrderFinalizationAutomateService, process), SysOperationExecutionMode::Synchronous);
}
